#include <vector>
#include <algorithm>

class Solution {
public:
    int minimizedMaximum(int n, std::vector<int>& quantities) {
        auto canDistribute = [&](int x) -> bool {
            long long stores = 0;
            for (int q : quantities) {
                stores += (q + x - 1) / x;
            }
            return stores <= n;
        };

        int low = 1, high = *std::max_element(quantities.begin(), quantities.end());
        int ans = high;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canDistribute(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int minimizedMaximum(int n, int[] quantities) {
        int low = 1, high = 0;
        for (int q : quantities) high = Math.max(high, q);
        int ans = high;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canDistribute(mid, n, quantities)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean canDistribute(int x, int n, int[] quantities) {
        long stores = 0;
        for (int q : quantities) {
            stores += (q + x - 1) / x;
        }
        return stores <= n;
    }
}

