var minimizedMaximum = function(n, quantities) {
    const canDistribute = (x) => {
        let stores = 0;
        for (const q of quantities) {
            stores += Math.ceil(q / x);
        }
        return stores <= n;
    };

    let low = 1, high = Math.max(...quantities);
    let ans = high;

    while (low <= high) {
        const mid = (low + high) >> 1;
        if (canDistribute(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
